-- mistri store layout: command-staging, sqlite, version 2. Generated by scripts/store-layouts.mjs; never edit by hand.
CREATE TABLE "__mistri_command_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  version INTEGER NOT NULL CHECK (version = 6)
);
CREATE TABLE "__mistri_command_receipt" (
  id TEXT COLLATE BINARY PRIMARY KEY NOT NULL,
  app_id TEXT COLLATE BINARY NOT NULL,
  store_id TEXT COLLATE BINARY NOT NULL,
  source_id TEXT COLLATE BINARY NOT NULL,
  realm TEXT COLLATE BINARY NOT NULL CHECK (realm IN ('tenant', 'platform')),
  tenant_id TEXT COLLATE BINARY NOT NULL,
  actor_id TEXT COLLATE BINARY NOT NULL,
  command_id TEXT COLLATE BINARY NOT NULL,
  command_version INTEGER NOT NULL CHECK (command_version > 0),
  idempotency_key TEXT COLLATE BINARY NOT NULL,
  fingerprint TEXT NOT NULL,
  result_json TEXT NOT NULL CHECK (json_valid(result_json) AND length(CAST(result_json AS BLOB)) <= 16384),
  request_id TEXT NOT NULL,
  completed_at TEXT NOT NULL,
  membership_id TEXT COLLATE BINARY NOT NULL,
  membership_version TEXT COLLATE BINARY NOT NULL,
  realm_version TEXT COLLATE BINARY NOT NULL,
  roles_json TEXT NOT NULL CHECK (json_valid(roles_json) AND length(CAST(roles_json AS BLOB)) <= 65536),
  deployment TEXT COLLATE BINARY NOT NULL,
  target TEXT NOT NULL,
  owners_json TEXT NOT NULL CHECK (json_valid(owners_json) AND json_type(owners_json) = 'array' AND length(CAST(owners_json AS BLOB)) <= 65536),
  keys_json TEXT NOT NULL CHECK (json_valid(keys_json) AND json_type(keys_json) = 'array' AND length(CAST(keys_json AS BLOB)) <= 2097152),
  changes_json TEXT NOT NULL CHECK (json_valid(changes_json) AND json_type(changes_json) = 'array' AND length(CAST(changes_json AS BLOB)) <= 4194304),
  manifest_json TEXT CHECK (manifest_json IS NULL OR (typeof(manifest_json) = 'text' AND json_valid(manifest_json) AND json_type(manifest_json) = 'array' AND length(CAST(manifest_json AS BLOB)) BETWEEN 1 AND 65536)),
  event_count INTEGER CHECK (event_count IS NULL OR (typeof(event_count) = 'integer' AND event_count BETWEEN 0 AND 32)),
  digest TEXT CHECK (digest IS NULL OR (typeof(digest) = 'text' AND length(digest) = 64 AND digest NOT GLOB '*[^0-9a-f]*')),
  actor_kind TEXT COLLATE BINARY NOT NULL CHECK (actor_kind IN ('person', 'public', 'service', 'link', 'assistant', 'job', 'decision', 'agent', 'flow')),
  proposal_id TEXT COLLATE BINARY CHECK (proposal_id IS NULL OR (typeof(proposal_id) = 'text' AND length(CAST(proposal_id AS BLOB)) BETWEEN 1 AND 128)),
  CHECK (realm = 'tenant' OR tenant_id = ''),
  CHECK ((manifest_json IS NULL) = (event_count IS NULL) AND (manifest_json IS NULL) = (digest IS NULL)),
  UNIQUE (app_id, store_id, source_id, realm, tenant_id, actor_id, command_id, command_version, idempotency_key)
);
CREATE INDEX "__mistri_command_receipt_completed" ON "__mistri_command_receipt" (completed_at);
CREATE TABLE "__mistri_command_audit_part" (
  receipt_id TEXT COLLATE BINARY NOT NULL REFERENCES "__mistri_command_receipt" (id) ON DELETE CASCADE,
  target_index INTEGER NOT NULL CHECK (target_index >= 0),
  part INTEGER NOT NULL CHECK (part >= 1),
  changes_json TEXT NOT NULL CHECK (json_valid(changes_json) AND json_type(changes_json) = 'array' AND length(CAST(changes_json AS BLOB)) <= 4194304),
  PRIMARY KEY (receipt_id, target_index, part)
);
CREATE TABLE "__mistri_command_link" (
  id TEXT COLLATE BINARY PRIMARY KEY NOT NULL,
  app_id TEXT COLLATE BINARY NOT NULL,
  tenant_id TEXT COLLATE BINARY NOT NULL,
  resource TEXT COLLATE BINARY NOT NULL,
  row_key TEXT COLLATE BINARY NOT NULL,
  name TEXT COLLATE BINARY NOT NULL,
  expires_at INTEGER NOT NULL CHECK (expires_at > 0),
  uses_left INTEGER CHECK (uses_left IS NULL OR (typeof(uses_left) = 'integer' AND uses_left >= 0)),
  revoked_at INTEGER,
  created_at INTEGER NOT NULL,
  created_by TEXT COLLATE BINARY NOT NULL,
  command TEXT COLLATE BINARY NOT NULL,
  receipt TEXT COLLATE BINARY NOT NULL,
  opens INTEGER NOT NULL CHECK (opens >= 0),
  last_opened_at INTEGER,
  row_stamp TEXT CHECK (row_stamp IS NULL OR (typeof(row_stamp) = 'text' AND length(CAST(row_stamp AS BLOB)) BETWEEN 1 AND 512))
);
CREATE INDEX "__mistri_command_link_row" ON "__mistri_command_link" (app_id, resource, row_key);
CREATE INDEX "__mistri_command_link_expires" ON "__mistri_command_link" (expires_at);
CREATE TABLE "__mistri_command_proposal" (
  id TEXT COLLATE BINARY PRIMARY KEY NOT NULL,
  app_id TEXT COLLATE BINARY NOT NULL,
  tenant_id TEXT COLLATE BINARY NOT NULL,
  command TEXT COLLATE BINARY NOT NULL,
  target TEXT COLLATE BINARY,
  input TEXT NOT NULL CHECK (json_valid(input) AND json_type(input) = 'object' AND length(CAST(input AS BLOB)) <= 65536),
  actor_kind TEXT COLLATE BINARY NOT NULL CHECK (actor_kind IN ('assistant', 'job', 'decision', 'agent', 'flow')),
  actor TEXT COLLATE BINARY NOT NULL,
  model TEXT,
  model_version TEXT,
  cost_micros INTEGER CHECK (cost_micros IS NULL OR (typeof(cost_micros) = 'integer' AND cost_micros >= 0)),
  evidence TEXT NOT NULL CHECK (json_valid(evidence) AND json_type(evidence) = 'array' AND length(CAST(evidence AS BLOB)) <= 65536),
  reason TEXT NOT NULL CHECK (length(CAST(reason AS BLOB)) <= 2048),
  state TEXT COLLATE BINARY NOT NULL CHECK (state IN ('proposed', 'approved', 'dismissed', 'expired', 'failed')),
  decided_by TEXT COLLATE BINARY,
  decided_at INTEGER,
  receipt_id TEXT COLLATE BINARY,
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL CHECK (expires_at > created_at),
  CHECK ((state = 'proposed') = (decided_at IS NULL))
);
CREATE INDEX "__mistri_command_proposal_state" ON "__mistri_command_proposal" (app_id, tenant_id, state, created_at);
CREATE INDEX "__mistri_command_proposal_created" ON "__mistri_command_proposal" (created_at);
CREATE TABLE "__mistri_command_provenance" (
  id TEXT COLLATE BINARY PRIMARY KEY NOT NULL,
  app_id TEXT COLLATE BINARY NOT NULL,
  tenant_id TEXT COLLATE BINARY NOT NULL,
  resource TEXT COLLATE BINARY NOT NULL,
  row_key TEXT COLLATE BINARY NOT NULL,
  field TEXT COLLATE BINARY,
  actor_kind TEXT COLLATE BINARY NOT NULL CHECK (actor_kind IN ('assistant', 'job', 'decision', 'agent', 'flow')),
  actor TEXT COLLATE BINARY NOT NULL,
  evidence TEXT NOT NULL CHECK (json_valid(evidence) AND json_type(evidence) = 'array' AND length(CAST(evidence AS BLOB)) <= 65536),
  created_at INTEGER NOT NULL,
  confirmed_by TEXT COLLATE BINARY,
  confirmed_at INTEGER,
  CHECK ((confirmed_by IS NULL) = (confirmed_at IS NULL))
);
CREATE INDEX "__mistri_command_provenance_row" ON "__mistri_command_provenance" (app_id, tenant_id, resource, row_key);
CREATE TABLE "__mistri_sequence_number" (
  app_id TEXT COLLATE BINARY NOT NULL,
  store_id TEXT COLLATE BINARY NOT NULL,
  source_id TEXT COLLATE BINARY NOT NULL,
  realm TEXT COLLATE BINARY NOT NULL CHECK (realm IN ('tenant', 'platform')),
  tenant_id TEXT COLLATE BINARY NOT NULL,
  name TEXT COLLATE BINARY NOT NULL,
  per TEXT COLLATE BINARY NOT NULL,
  value INTEGER NOT NULL CHECK (value > 0),
  PRIMARY KEY (app_id, store_id, source_id, realm, tenant_id, name, per)
);
CREATE TABLE "__mistri_sequence_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  version INTEGER NOT NULL CHECK (version = 1)
);
CREATE TABLE "__mistri_staged_file" (
  id_hash TEXT COLLATE BINARY PRIMARY KEY CHECK (length(id_hash) = 64),
  app_id TEXT COLLATE BINARY NOT NULL,
  store_id TEXT COLLATE BINARY NOT NULL,
  source_id TEXT COLLATE BINARY NOT NULL,
  realm TEXT COLLATE BINARY NOT NULL CHECK (realm IN ('tenant', 'platform')),
  tenant_id TEXT COLLATE BINARY NOT NULL,
  owner TEXT COLLATE BINARY NOT NULL,
  command_id TEXT COLLATE BINARY NOT NULL,
  field TEXT COLLATE BINARY NOT NULL,
  name TEXT NOT NULL,
  type TEXT NOT NULL,
  size INTEGER NOT NULL CHECK (size >= 0),
  data BLOB NOT NULL,
  expires_at INTEGER NOT NULL
);
CREATE INDEX "__mistri_staged_file_owner" ON "__mistri_staged_file" (app_id, owner, expires_at);
CREATE INDEX "__mistri_staged_file_expires" ON "__mistri_staged_file" (expires_at);
CREATE TABLE "__mistri_staged_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  version INTEGER NOT NULL CHECK (version = 2)
);
